import os
import re
from typing import List, Dict, Any, Tuple

import requests

PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _validate_text(text: str) -> None:
    if not isinstance(text, str):
        raise TypeError("text must be a string")


def _build_request(text: str, attributes: List[str], api_key: str, languages: List[str] = None) -> Dict[str, Any]:
    body: Dict[str, Any] = {
        "comment": {"text": text},
        "requestedAttributes": {attr: {} for attr in attributes},
        "doNotStore": True,
    }
    if languages:
        body["languages"] = languages
    return body


def _local_fallback_spans(text: str) -> List[Tuple[int, int]]:
    patterns = [
        r"\b(?:kill|murder|rape|bomb|hate)\b",
        r"\b(?:nigger|faggot|kike|retard)\b",
        r"\b(?:suicide|self-harm|cut myself|end my life)\b",
        r"\b(?:stupid|idiot|moron)\b",
    ]
    spans: List[Tuple[int, int]] = []
    for pattern in patterns:
        for m in re.finditer(pattern, text, flags=re.IGNORECASE):
            spans.append((m.start(), m.end()))
    spans.sort()
    merged: List[Tuple[int, int]] = []
    for s, e in spans:
        if not merged or s > merged[-1][1]:
            merged.append((s, e))
        else:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
    return merged


def _score_to_spans(text: str, response: Dict[str, Any], threshold: float) -> List[Tuple[int, int]]:
    matches: List[Tuple[int, int]] = []
    for attr_payload in (response.get("attributeScores") or {}).values():
        score = (((attr_payload or {}).get("summaryScore") or {}).get("value"))
        if score is None or score < threshold:
            continue
        spans = (((attr_payload or {}).get("spanScores")) or [])
        for span in spans:
            begin = span.get("begin")
            end = span.get("end")
            if begin is None or end is None:
                continue
            matches.append((int(begin), int(end)))
    matches.sort()
    merged: List[Tuple[int, int]] = []
    for s, e in matches:
        if not merged or s > merged[-1][1]:
            merged.append((s, e))
        else:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
    return merged


def _redact_text(text: str, spans: List[Tuple[int, int]], redaction_token: str = "[REDACTED]") -> str:
    if not spans:
        return text
    out = []
    last = 0
    for start, end in spans:
        start = max(0, min(len(text), start))
        end = max(0, min(len(text), end))
        if start < last:
            start = last
        if end <= start:
            continue
        out.append(text[last:start])
        out.append(redaction_token)
        last = end
    out.append(text[last:])
    return "".join(out)


def moderate_text(
    text: str,
    attributes: List[str] = None,
    threshold: float = 0.5,
    redact: bool = True,
    redaction_token: str = "[REDACTED]",
) -> Dict[str, Any]:
    """
    Flags or redacts unsafe spans using Perspective API.

    Returns:
        {
            "unsafe": bool,
            "spans": [{"start": int, "end": int, "snippet": str}],
            "redacted_text": str,
            "provider": "perspective",
            "scores": {...}
        }
    """
    _validate_text(text)

    if attributes is None:
        attributes = ["TOXICITY", "SEVERE_TOXICITY", "IDENTITY_ATTACK", "INSULT", "PROFANITY", "THREAT"]

    api_key = os.getenv("PERSPECTIVE_API_KEY")
    scores: Dict[str, Any] = {}
    spans: List[Tuple[int, int]] = []

    if api_key:
        payload = _build_request(text, attributes, api_key)
        params = {"key": api_key}
        try:
            resp = requests.post(
                PERSPECTIVE_API_URL,
                params=params,
                json=payload,
                timeout=15,
            )
            resp.raise_for_status()
            data = resp.json()
            scores = data.get("attributeScores", {})
            spans = _score_to_spans(text, data, threshold)
        except Exception:
            spans = _local_fallback_spans(text)
    else:
        spans = _local_fallback_spans(text)

    unsafe = len(spans) > 0
    annotated_spans = [
        {"start": s, "end": e, "snippet": text[s:e]}
        for s, e in spans
    ]

    result = {
        "unsafe": unsafe,
        "spans": annotated_spans,
        "redacted_text": _redact_text(text, spans, redaction_token) if redact else text,
        "provider": "perspective",
        "scores": scores,
    }
    return result


def flag_unsafe_spans(text: str, threshold: float = 0.5) -> Dict[str, Any]:
    return moderate_text(text=text, threshold=threshold, redact=False)


def redact_unsafe_spans(text: str, threshold: float = 0.5, redaction_token: str = "[REDACTED]") -> str:
    return moderate_text(text=text, threshold=threshold, redact=True, redaction_token=redaction_token)["redacted_text"]
